examples:
import { Select } from 'moraine'

<Select
  items={[]}
  emptyRender={(state) => <button onClick={() => state.close()}>No options. Close</button>}
/>

import { Combobox } from 'moraine'

<Combobox
  items={[
    { label: <strong>Apple</strong>, value: 'apple' },
    { label: <strong>Pear</strong>, value: 'pear' },
  ]}
  getItemLabel={(item) => String(item.value)}
/>

import { MultiSelect } from 'moraine'

<MultiSelect
  items={[
    { label: 'Admin', value: 'admin' },
    { label: 'Guest', value: 'guest' },
  ]}
  isItemDisabled={(item, values) => item.value === 'guest' && values.includes('admin')}
/>

import { Select } from 'moraine'

<Select
  items={[
    { label: 'Free', value: 'free' },
    { label: 'Pro', value: 'pro' },
  ]}
  itemRender={(state) => (
    <span>
      {state.item.label}
      {state.selected ? ' ✓' : ''}
    </span>
  )}
/>

props.typeDetails:
(string | {
  /** Unique selection and form value. Values compare by identity, so `1` and `'1'` differ. */
  value: string | number;
  /** Visual label. May be any JSX; when it is not a string, plain-text uses (typeahead,
filtering) fall back to `String(value)` unless `getItemLabel` is set. */
  label: JSX.Element;
  /** Whether this item cannot be selected. A disabled item is also left out of form submission. */
  disabled?: boolean;
  /** Icon rendered before the label in the default item content. Ignored when `itemRender` is set. */
  icon?: IconT.Name;
  /** Secondary text rendered under the label in the default item content. Ignored when `itemRender` is set. */
  description?: JSX.Element;
} | {
  /** Structural group discriminator. */
  type: 'group';
  /** Heading rendered above the group's items. Not selectable. */
  label: JSX.Element;
  /** Items in the group. Item values must be unique across the whole collection, not just the
group: a repeated value is ignored (the first occurrence wins). A group with no remaining
items, or none matching the current search, renders nothing. */
  children: (string | {
    /** Unique selection and form value. Values compare by identity, so `1` and `'1'` differ. */
    value: string | number;
    /** Visual label. May be any JSX; when it is not a string, plain-text uses (typeahead,
  filtering) fall back to `String(value)` unless `getItemLabel` is set. */
    label: JSX.Element;
    /** Whether this item cannot be selected. A disabled item is also left out of form submission. */
    disabled?: boolean;
    /** Icon rendered before the label in the default item content. Ignored when `itemRender` is set. */
    icon?: IconT.Name;
    /** Secondary text rendered under the label in the default item content. Ignored when `itemRender` is set. */
    description?: JSX.Element;
  })[];
} | {
  /** Structural separator discriminator. */
  type: 'separator';
})[]

examples:
import { Select } from 'moraine'

<Select
  items={[
    { label: 'Apple', value: 'apple' },
    { type: 'separator' },
    {
      type: 'group',
      label: 'Citrus',
      children: [
        { label: 'Lemon', value: 'lemon' },
        { label: 'Lime', value: 'lime', disabled: true },
      ],
    },
    { label: 'Pear', value: 'pear' },
  ]}
/>

import { Select } from 'moraine'

<Select
  items={['Small', 'Large']}
  clearable
  translations={{ clear: 'Remove size', placeholder: 'Pick a size' }}
/>
